export function GlobalState({
  storeKey = "{{storeKey}}",
  value = "{{value}}",
  subscriberCount = "{{subscriberCount}}",
  accent = "{{accent}}",
}) {
  const n = Number(subscriberCount);
  const subs = ["Header", "Sidebar", "Profile card"].filter((_, i) => i < n);
  return (
    <div style={{ font: "12px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 18, borderRadius: 12, width: 300, boxSizing: "border-box" }}>
      <div style={{ textAlign: "center", fontWeight: 700, fontSize: 11, fontFamily: "ui-monospace, monospace", padding: 10, borderRadius: 8, marginBottom: 14, background: accent }}>store.{storeKey} = "{value}"</div>
      <div style={{ display: "flex", gap: 8 }}>
        {subs.map((s) => <span key={s} style={{ flex: 1, textAlign: "center", padding: "10px 4px", borderRadius: 8, background: "#24143010", fontSize: 11, fontWeight: 600 }}>{s}</span>)}
      </div>
    </div>
  );
}
